head.script:
/*
 * 샘플 — udc_bulkFileSaver 활용
 * UDC 가 파일 다이얼로그 + fileMap + loadList/save 공통 로직 캡슐화
 * 화면은 그리드/컬럼/도메인 로직만 담당
 */

/**
 * @event 
 * @name onpageload
 * @description 화면이 열렸을 때 엔진 초기화 작업이 끝난 뒤에 발생하는 이벤트. 화면 초기화에 필요한 코드를 작성한다.
 */
scwin.onpageload = async function () {
	await scwin.loadList();
}; 

/**
 * @event
 * @name btn_reload_onclick
 * @description 데이터 재조회 버튼 click 이벤트
*/ 
scwin.btn_reload_onclick = async function () {
	await scwin.loadList();
};

/**
 * @event
 * @name btnAddRow_onclick
 * @description 데이터 행추가 버튼 click 이벤트
*/ 
scwin.btnAddRow_onclick = function () {
	// 행추가 시 uid 값을 업데이트
	const uid = "NEW_" + new Date().getTime() + "_" + Math.floor(Math.random() * 10000);
	const newIdx = dltRowDatas.getRowCount();

	dltRowDatas.insertRow(newIdx, {
		id: 0, 
		uid: uid, 
		empNo: "", 
		empName: "", 
		fileName: "", 
		fileSize: 0, 
		fileChanged: ""
	});

	dltRowDatas.setCellData(newIdx, "uid", uid);
	spnCount.setValue(dltRowDatas.getRowCount());
};

/**
 * @event
 * @name btnAddRow_onclick
 * @description 데이터 행삭제 버튼 click 이벤트
*/ 
scwin.btnDelRow_onclick = function () {
	const idx = grd_rows.getFocusedRowIndex();
	if (idx < 0) { $c.win.alert("삭제할 행을 선택하세요."); return; }

	udcSaver.detachFile(idx, dltRowDatas);
	dltRowDatas.removeRow(idx);
	spnCount.setValue(dltRowDatas.getRowCount());
};

/**
 * @event
 * @name grd_rows_oncellclick
 * @description gridView cell click 이벤트
*/ 
scwin.grd_rows_oncellclick = function (rowIndex, columnIndex, columnId) {
	if (columnId === "btn_pick") {
		// 수정 시 uid 값을 업데이트
		const uid = "MOD_" + new Date().getTime() + "_" + Math.floor(Math.random() * 10000);
		dltRowDatas.setCellData(row, "uid", uid);

		udcSaver.attachFile(rowIndex, dltRowDatas);
	} else if (columnId === "btn_clear") {
		udcSaver.detachFile(rowIndex, dltRowDatas);
	}
};

/**
 * @method
 * @name grd_rows_oncellclick
 * @description 재조회 통신 submission 호출
*/ 
scwin.loadList = async function () {
	const sbmOptions = {
		id : "sbmBulkUploadList",
		action : "/sample/bulkFileUpload/list",
		method : "get",
		submitDoneHandler : scwin.sbmBulkUploadList_submitdone,
		isProcessMsg : false
	};

	const res = await $c.sbm.executeDynamic(sbmOptions);

	 // 진행 중 통신이 있어 이번 호출은 건너뜀
	if (res && res.skipped) { return; }
};

/**
 * @method
 * @name sbmBulkUploadList_submitdone
 * @description 재조회 통신 submission의 submitDoneHandler 함수
*/ 
scwin.sbmBulkUploadList_submitdone = function (e) {
	const raw = (e.responseJSON && e.responseJSON.list) || [];

	dltRowDatas.setJSON(raw.map(function (r) {
		return {
			id: r.id, uid: "R_" + r.id,
			empNo: r.empNo, empName: r.empName,
			fileName: r.fileName || "", fileSize: r.fileSize || 0,
			fileChanged: ""
		};
	}));

	spnCount.setValue(dltRowDatas.getRowCount());
};

/**
 * @event
 * @name btnSave_onclick
 * @description 저장 버튼 click 이벤트 — UDC.save 사용
*/ 
scwin.btnSave_onclick = async function () {
	await udcSaver.save({
		dataList: dltRowDatas,
		dataListId: "dltList",
		saveUrl:  "/sample/bulkFileUpload",
		onValidate: function (row) {
			if ($c.util.isEmpty(row.empNo))   return "사번을 입력하세요.";
			if ($c.util.isEmpty(row.empName)) return "이름을 입력하세요.";
			return null;
		},
		onSuccess: function (res) {
			$c.win.alert("저장 완료: 신규 " + res.insertedCount + "건, 수정 " + res.updatedCount + "건, 삭제 " + res.deletedCount + "건");
		},
		onAfterSave: scwin.loadList
	});
};
